jest.mock("rollup", () => ({
  rollup: jest.fn().mockResolvedValue({}),
  watch: jest.fn().mockReturnValue({ on: jest.fn(), close: jest.fn() }),
  defineConfig: (config: any) => config,
}));

jest.mock("../../src/rollup/fluent-to-rollupfs", () =>
  jest.fn().mockReturnValue({}),
);

jest.mock("../../src/rollup/rollup-fs-adapter", () => ({
  RollupFsAdapter: jest.fn().mockImplementation(() => ({})),
}));

jest.mock("../../src/web-fs-loader", () =>
  jest.fn().mockReturnValue({ name: "web-fs-loader" }),
);

jest.mock("../../src/utils/browser", () => ({
  isBrowserOrWorkerEnvironment: jest.fn().mockReturnValue(false),
}));

import { rollup, watch } from "../../src/rollup";

const makeFs = () =>
  ({
    readFileSync: jest.fn(),
    writeFileSync: jest.fn(),
    statSync: jest.fn(),
    readdirSync: jest.fn(),
    mkdirSync: jest.fn(),
    copyFileSync: jest.fn(),
    realpathSync: jest.fn(),
    renameSync: jest.fn(),
    rmSync: jest.fn(),
    lstatSync: jest.fn(),
  }) as any;

describe("rollup wrapper", () => {
  beforeEach(() => {
    jest.clearAllMocks();
    delete (globalThis as any).__rollupFs;
  });

  describe("rollup()", () => {
    test("should reject when fs is not provided", async () => {
      await expect(rollup({} as any)).rejects.toThrow(
        "A filesystem must be provided, but none was found on options.fs",
      );
    });

    test("should convert the FileSystem via fluentToRollupfs and pass it to bareRollup", async () => {
      const bareRollupMock = require("rollup").rollup;
      const fluentToRollupfs = require("../../src/rollup/fluent-to-rollupfs");
      const mockRollupFs = { mocked: "rollupfs" };
      fluentToRollupfs.mockReturnValue(mockRollupFs);

      const fs = makeFs();
      await rollup({ fs, input: "src/index.ts" });

      expect(fluentToRollupfs).toHaveBeenCalledWith(fs);
      expect(bareRollupMock).toHaveBeenCalledWith(
        expect.objectContaining({ fs: mockRollupFs }),
      );
    });

    test("should set globalThis.__rollupFs", async () => {
      const fs = makeFs();
      await rollup({ fs, input: "src/index.ts" });
      expect((globalThis as any).__rollupFs).toBeDefined();
    });
  });

  describe("watch()", () => {
    test("should throw when called in a browser/worker environment", () => {
      const {
        isBrowserOrWorkerEnvironment,
      } = require("../../src/utils/browser");
      isBrowserOrWorkerEnvironment.mockReturnValueOnce(true);
      expect(() => watch({ fs: makeFs(), input: "src/index.ts" })).toThrow(
        "watch() is not supported in browser/worker environments",
      );
    });

    test("should throw when fs is not provided", () => {
      expect(() => watch({} as any)).toThrow(
        "A filesystem must be provided, but none was found on options.fs",
      );
    });

    test("should convert the FileSystem via fluentToRollupfs and pass it to rollupWatch", () => {
      const rollupWatchMock = require("rollup").watch;
      const fluentToRollupfs = require("../../src/rollup/fluent-to-rollupfs");
      const mockRollupFs = { mocked: "rollupfs" };
      fluentToRollupfs.mockReturnValue(mockRollupFs);

      const fs = makeFs();
      watch({ fs, input: "src/index.ts" });

      expect(fluentToRollupfs).toHaveBeenCalledWith(fs);
      expect(rollupWatchMock).toHaveBeenCalledWith(
        expect.objectContaining({ fs: mockRollupFs }),
      );
    });

    test("should set globalThis.__rollupFs", () => {
      const fs = makeFs();
      watch({ fs, input: "src/index.ts" });
      expect((globalThis as any).__rollupFs).toBeDefined();
    });

    test("should not inject webFsLoader (watch is Node-only, never invoked in browser)", () => {
      const webFsLoader = require("../../src/web-fs-loader");
      const fs = makeFs();
      watch({ fs, input: "src/index.ts" });
      expect(webFsLoader).not.toHaveBeenCalled();
    });
  });
});
